def kthDistinctOrdering(nums, k):
    n = len(nums)
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i
    cnt = {}
    for x in nums:
        cnt[x] = cnt.get(x, 0) + 1
    vals = sorted(cnt)

    def ways(total):
        r = fact[total]
        for v in vals:
            r //= fact[cnt[v]]
        return r

    k -= 1
    res = []
    for pos in range(n):
        left = n - pos - 1
        for v in vals:
            if cnt[v] == 0:
                continue
            cnt[v] -= 1
            w = ways(left)
            if k < w:
                res.append(v)
                break
            k -= w
            cnt[v] += 1
    return res
